import{_ as t,o as c,c as d,a3 as o}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"命令行概览","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"命令行概览 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/cli/overview"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/overview"}]]},"headers":[],"relativePath":"zh/clice/cli/overview.md","filePath":"zh/clice/cli/overview.md","lastUpdated":1793393027000}'),a={name:"zh/clice/cli/overview.md"};function r(i,e,l,n,s,h){return c(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="命令行概览" tabindex="-1">命令行概览 <a class="header-anchor" href="#命令行概览" aria-label="Permalink to &quot;命令行概览&quot;">​</a></h1><p>clice 只有一个二进制。编辑器启动 <code>clice serve</code> 并通过 LSP 与它通信；其余子命令在终端里驱动同一个引擎，共用它的编译数据库处理、缓存和索引。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>页面</th></tr></thead><tbody><tr><td><code>serve</code></td><td>启动语言服务器。编辑器会替你启动，见编辑器设置。</td><td><a href="./../guide/editors">editors</a></td></tr><tr><td><code>lint</code></td><td>用 worker 池对每个翻译单元运行 clang-tidy。</td><td><a href="./lint">lint</a></td></tr><tr><td><code>index</code></td><td>提前为项目建立索引，让服务器热启动。</td><td><a href="./">index</a></td></tr><tr><td><code>format</code></td><td>用 clang-format 格式化项目中的文件。</td><td><a href="./format">format</a></td></tr><tr><td><code>inspect</code></td><td>对一个源文件运行某一项功能，把原始结果打印成 JSON。</td><td></td></tr><tr><td><code>command</code></td><td>显示一个文件编译时所用的命令，并为其他工具转换编译命令。</td><td><a href="./command">command</a></td></tr><tr><td><code>query</code></td><td>向持久化索引查询符号、引用、调用图和文件。</td><td><a href="./query">query</a></td></tr><tr><td><code>refactor</code></td><td>依据持久化索引在整个项目中重命名一个符号。</td><td><a href="./refactor">refactor</a></td></tr><tr><td><code>analyze</code></td><td>报告重构所需的事实，例如模块依赖和循环依赖。</td><td><a href="./analyze">analyze</a></td></tr><tr><td><code>modularize</code></td><td>把第三方库封装成 C++20 模块，把程序改写成模块单元。</td><td><a href="./modularize">modularize</a></td></tr><tr><td><code>scan</code></td><td>扫描构建的 include 和模块依赖，并为扫描计时。</td><td><a href="./scan">scan</a></td></tr></tbody></table><p><code>inspect</code> 现在已可使用但还没有页面，它的操作和选项通过 <code>clice inspect --help</code> 查看。</p><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><p>每个子命令都以同样的方式接受参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clice &lt;command&gt; [&lt;operation&gt;] [&lt;target&gt;...] [--option...]</span></span></code></pre></div><ul><li>能做几件事的命令，用紧跟其后的一个词指明要做哪一件：<code>clice query references</code>、<code>clice index stats</code>、<code>clice analyze modules edge</code>。有一项首要职能的命令，后面不跟词时就执行这项职能：<code>clice index</code> 建立索引，<code>clice analyze modules</code> 给出概览，<code>clice command &lt;file&gt;</code> 显示该文件的编译命令。在任何命令或操作后面加上 <code>--help</code>，都会列出它接受的参数。</li><li>目标，即操作所针对的符号或文件，跟在操作之后：<code>clice query references &quot;shapes::Circle::area&quot;</code>、<code>clice query document-symbols src/main.cpp</code>。凡是接受符号的地方，都用<a href="./query#locators">定位串</a>（locator）指明符号；文件则用路径指明，可以相对于当前目录，也可以是绝对路径；命令行上的其他路径也都如此，例如分区文件或输出目录。</li><li>选项放在操作之后。一个选项要取多个值时，就重复给出它：<code>--scope &#39;src/**&#39; --scope &#39;include/**&#39;</code>。</li><li><code>--workspace &lt;dir&gt;</code> 指定项目根目录；不给出时，命令作用于当前目录所在的项目，查找方式与 git 查找仓库相同：从当前目录向上，最近的一个含有 <code>clice.toml</code>、<code>.clice/config.toml</code> 或 <code>compile_commands.json</code> 的目录（直接含有，或在其 <code>build/</code> 目录中含有），一个都找不到时就是当前目录本身（<code>inspect</code> 与编辑器一样，从文件所在位置向上查找）。命令无法接受的配置——无法解析的文件、类型错误的值、无法遵照的选项——会使命令以退出码 2 失败，每个问题都连同它在文件中的位置一起给出；<code>--configuration &lt;tag&gt;</code> 固定构建配置，其优先级高于编辑器持久化的选择（参见<a href="./../guide/configuration#switching-configurations">切换配置</a>）；<code>-j</code>、<code>--jobs &lt;n&gt;</code> 指定 <code>index</code>、<code>lint</code> 和 <code>format</code> 同时处理多少个单元或文件；<code>--log-level</code> 设置向 stderr 输出哪些日志，默认为警告和错误（编辑器会显示 <code>serve</code> 的 stderr，它从 <code>info</code> 级别起输出）；无论该选项取什么值，<code>serve</code>、<code>index</code> 和 <code>lint</code> 的会话日志都保留 <code>info</code> 级别。</li></ul>',8)])])}const f=t(a,[["render",r]]);export{m as __pageData,f as default};
